-- Scenario: the Google tag settings the documentation's screenshots show
--
-- The page under docs/<locale>/4-console/ about the Google tag photographs
-- the form with a Tag Manager container ID saved in the Google tag gateway
-- mode. A gateway path is generated by the server at random, so the path the
-- screenshots show is written here as a literal instead of saved from the
-- form. The settings decide what the tenant's site loads, and the Google tag
-- suite of 570_google_tag.sql deletes its tenant's settings while it runs
-- beside the screenshots, so the documentation has a tenant of its own.
--
-- Applied by e2e/tests/admin.docs-screenshots.setup.ts. Every row is written
-- with ON CONFLICT, so it can be applied any number of times.
-- public_id values are hard-coded in e2e/src/scenarios/docs-google-tag.ts.
--   tenant DtagTNNTAAA1 (tag-docs.localhost / admin.tag-docs.localhost)
--   admin  DtagADMNAAA1 (tag-docs-admin@example.com)
--
-- ID band: 018f1140-000N-7000-8000-000000000001.

WITH tenant_seed AS (
    SELECT '018f1140-0001-7000-8000-000000000001'::uuid AS id
)
INSERT INTO tenants (
    id,
    public_id,
    domain,
    admin_domain,
    name,
    status,
    default_locale,
    supported_locales
)
SELECT
    ts.id,
    'DtagTNNTAAA1',
    'tag-docs.localhost:' || :'tenant_port',
    'admin.tag-docs.localhost:' || :'tenant_port',
    'Tag Docs Tenant',
    'active',
    'en',
    ARRAY['ja', 'en', 'ko', 'zh-Hans', 'zh-Hant']
FROM tenant_seed ts
ON CONFLICT (public_id) DO UPDATE
SET domain = EXCLUDED.domain,
    admin_domain = EXCLUDED.admin_domain,
    name = EXCLUDED.name,
    status = EXCLUDED.status,
    default_locale = EXCLUDED.default_locale,
    supported_locales = EXCLUDED.supported_locales;

\set seed_tenant DtagTNNTAAA1
\ir ../creator_roles.sql

WITH admin_user_seed AS (
    SELECT '018f1140-0002-7000-8000-000000000001'::uuid AS id
)
INSERT INTO users (
    id,
    tenant_id,
    public_id,
    email,
    password_hash,
    name,
    status,
    email_verified_at
)
SELECT
    aus.id,
    t.id,
    'DtagADMNAAA1',
    'tag-docs-admin@example.com',
    '$2a$10$IWG04mPtZmFUnCi7UTCT6uMdMwgBorh/EYQDZdmReiMcqdSpcNT9.',
    'Tag Docs E2E Admin',
    'active',
    NOW()
FROM admin_user_seed aus
JOIN tenants t ON t.public_id = 'DtagTNNTAAA1'
ON CONFLICT (public_id) DO UPDATE
SET tenant_id = EXCLUDED.tenant_id,
    email = EXCLUDED.email,
    password_hash = EXCLUDED.password_hash,
    name = EXCLUDED.name,
    status = EXCLUDED.status,
    email_verified_at = EXCLUDED.email_verified_at;

INSERT INTO tenant_user_roles (id, user_id, role, tenant_id)
SELECT
    '018f1140-0003-7000-8000-000000000001'::uuid,
    u.id,
    'tenant_admin',
    u.tenant_id
FROM users u
WHERE u.public_id = 'DtagADMNAAA1'
ON CONFLICT (user_id, role) DO NOTHING;

INSERT INTO tenant_analytics_settings (
    tenant_id,
    ga4_measurement_id,
    gtm_container_id,
    serving_mode,
    server_container_url,
    gateway_path
)
SELECT
    t.id,
    NULL,
    'GTM-ABC1234',
    'gateway',
    NULL,
    '_k7m2qx4pzwd3rt6v'
FROM tenants t
WHERE t.public_id = 'DtagTNNTAAA1'
ON CONFLICT (tenant_id) DO UPDATE
SET ga4_measurement_id = EXCLUDED.ga4_measurement_id,
    gtm_container_id = EXCLUDED.gtm_container_id,
    serving_mode = EXCLUDED.serving_mode,
    server_container_url = EXCLUDED.server_container_url,
    gateway_path = EXCLUDED.gateway_path,
    updated_at = NOW();
